package com.bank.platform.service;

import java.util.logging.Logger;

// One microservice with its OWN replicas and autoscaler settings.
public class ServiceGroup {
    private static final Logger log = Logger.getLogger(ServiceGroup.class.getName());
    private final String name;
    private final int minReplicas;
    private final int maxReplicas;
    private final int rpsPerReplica;
    private int replicas;

    public ServiceGroup(String name, int min, int max, int rpsPerReplica) {
        this.name = name;
        this.minReplicas = min;
        this.maxReplicas = max;
        this.rpsPerReplica = rpsPerReplica;
        this.replicas = min;
    }

    // Independent auto-scaling: only THIS service reacts to ITS load.
    public int autoScale(int currentRps) {
        int desired = (int) Math.ceil((double) currentRps / rpsPerReplica);
        desired = Math.max(minReplicas, Math.min(maxReplicas, desired));
        if (desired != replicas) {
            int from = replicas, to = desired;
            log.info(() -> "AUTOSCALE " + name + ": rps=" + currentRps
                    + " replicas " + from + " -> " + to);
            replicas = desired;
        } else {
            log.fine(() -> "NO-SCALE " + name + ": replicas stay " + replicas);
        }
        return replicas;
    }

    public String getName() { return name; }
    public int getReplicas() { return replicas; }
    public int capacity() { return replicas * rpsPerReplica; }
}
