package com.bank.platform.gateway;

import com.bank.platform.service.ServiceGroup;
import java.util.*;
import java.util.logging.Logger;

// Single entry point: route by path + per-service rate limiting (load shedding).
public class ApiGateway {
    private static final Logger log = Logger.getLogger(ApiGateway.class.getName());
    private final Map<String, ServiceGroup> routes = new HashMap<>();
    private final Map<String, Integer> rateLimitPerSec = new HashMap<>();

    public void addRoute(String path, ServiceGroup service, int rateLimit) {
        routes.put(path, service);
        rateLimitPerSec.put(path, rateLimit);
    }

    // Accept up to the rate limit; shed the rest to protect the service.
    public int route(String path, int incomingRps) {
        ServiceGroup svc = routes.get(path);
        int limit = rateLimitPerSec.getOrDefault(path, Integer.MAX_VALUE);
        int accepted = Math.min(incomingRps, limit);
        if (incomingRps > limit) {
            log.warning(() -> "GATEWAY rate-limit " + path + ": shed "
                    + (incomingRps - limit) + " rps (429)");
        }
        log.info(() -> "GATEWAY route " + path + " -> " + svc.getName()
                + " accepted " + accepted + " rps");
        svc.autoScale(accepted);
        return accepted;
    }
}
