package com.bank.platform.async;

import java.util.concurrent.*;
import java.util.logging.Logger;

// Async offload: publish events; consumers (scaled by lag) drain steadily.
public class EventBus {
    private static final Logger log = Logger.getLogger(EventBus.class.getName());
    private final BlockingQueue<String> topic = new LinkedBlockingQueue<>();

    public void publish(String event) {
        topic.offer(event);
        log.fine(() -> "PUBLISH " + event + " (lag=" + topic.size() + ")");
    }

    public int lag() { return topic.size(); }

    // Consumers scale on lag (KEDA-style): more lag -> more consumers.
    public int desiredConsumers(int lagPerConsumer) {
        return Math.max(1, (int) Math.ceil((double) topic.size() / lagPerConsumer));
    }

    public void drain(int n) { for (int i = 0; i < n && topic.poll() != null; i++) { } }
}
