package com.bank.platform;

import com.bank.platform.async.EventBus;
import com.bank.platform.gateway.ApiGateway;
import com.bank.platform.resilience.CircuitBreaker;
import com.bank.platform.service.ServiceGroup;
import java.util.logging.*;

public class PlatformDemo {
    public static void main(String[] args) {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) h.setFormatter(new BankLogFormatter());
        Logger log = Logger.getLogger(PlatformDemo.class.getName());

        // Each microservice has its own scaling profile.
        ServiceGroup transfer = new ServiceGroup("transfer-service", 3, 30, 500);
        ServiceGroup loan = new ServiceGroup("loan-service", 2, 6, 200);
        ServiceGroup statement = new ServiceGroup("statement-service", 2, 10, 100);

        ApiGateway gateway = new ApiGateway();
        gateway.addRoute("/api/v1/transfers", transfer, 12000); // rate cap
        gateway.addRoute("/api/v1/loans", loan, 1000);

        // Festival spike: transfers surge, loans quiet. Only transfer scales.
        log.info("=== Festival spike: transfers surge, loans quiet ===");
        gateway.route("/api/v1/transfers", 10000);  // transfer scales out
        gateway.route("/api/v1/loans", 300);         // loan stays small

        // Buggy client floods transfers beyond the rate cap -> gateway sheds.
        log.severe("Buggy client floods transfers with 15000 rps");
        gateway.route("/api/v1/transfers", 15000);   // shed 3000, cap at 12000

        // Slow statement work offloaded asynchronously; consumers scale on lag.
        EventBus bus = new EventBus();
        for (int i = 0; i < 2500; i++) bus.publish("statement-for-transfer-" + i);
        int consumers = bus.desiredConsumers(500);
        statement.autoScale(consumers * 100);
        log.info("Async lag=" + bus.lag() + " -> desired consumers=" + consumers);

        // Statement downstream overloads: breaker isolates it, transfers safe.
        CircuitBreaker stmtBreaker = new CircuitBreaker(3);
        for (int i = 0; i < 4; i++) stmtBreaker.onFailure();
        log.warning("Statement breaker=" + stmtBreaker.getState()
                + " -> transfers keep flowing, failure isolated");

        log.info("Final replicas: transfer=" + transfer.getReplicas()
                + " loan=" + loan.getReplicas()
                + " statement=" + statement.getReplicas() + " (scaled independently)");
    }
}

